import{_ as e,o as r,c as s,a2 as t}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"索引管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/index-drives.md","filePath":"zh-HK/user-guide/settings/index-drives.md","lastUpdated":1787586465000}'),l={name:"zh-HK/user-guide/settings/index-drives.md"};function n(i,o,a,d,g,c){return r(),s("div",null,[...o[0]||(o[0]=[t('<h1 id="索引管理" tabindex="-1">索引管理 <a class="header-anchor" href="#索引管理" aria-label="Permalink to &quot;索引管理&quot;">​</a></h1><p>索引設定頁面用於精細化控制 Lertaro 針對本機硬碟、網路儲存、WSL 子系統以及自訂資料夾的索引範圍、重新整理策略與排除規則。頁面頂部包含五個標籤頁：<strong>本機磁碟機</strong>、<strong>網路磁碟機</strong>、<strong>WSL</strong>（偵測到發行版時自動顯示）、<strong>資料夾</strong>與<strong>排除規則</strong>。</p><h2 id="_1-本機磁碟機-local-drives" tabindex="-1">1. 本機磁碟機（Local Drives） <a class="header-anchor" href="#_1-本機磁碟機-local-drives" aria-label="Permalink to &quot;1. 本機磁碟機（Local Drives）&quot;">​</a></h2><ul><li><strong>頂部彙總狀態</strong>：展示當前已索引的實體磁碟機數量與總檔案/資料夾項目數，並提供<strong>重建索引</strong>按鈕觸發所有本機磁碟的全量重建。</li><li><strong>磁碟機列表行</strong>：每個實體分區獨立顯示一行： <ul><li><strong>啟用/禁用核取方塊</strong>：獨立開關該磁碟的索引。</li><li><strong>檔案系統與狀態</strong>：顯示底層檔案系統類型（NTFS、ReFS、FAT32、exFAT 等）、當前狀態與已索引項目數。</li><li><strong>單盤操作</strong>：每行提供獨立的<strong>重建</strong>與<strong>移除</strong>操作；在重建掃描進行時會動態提供<strong>停止</strong>按鈕。</li></ul></li><li><strong>即時監控機制</strong>：NTFS 與 ReFS 卷透過 Windows 系統的 USN 變更記錄檔實現毫秒級增量同步；FAT32 與 exFAT 卷透過檔案系統即時變更事件監聽。</li><li><strong>無縫重建保障</strong>：在某個磁碟重建期間，舊索引將繼續回應使用者的搜尋查詢，直到新索引構建完成時瞬間無縫替換，搜尋體驗絕不中斷。若重建過程被系統重啟或手動停止中斷，下次會自動從斷點繼續。</li></ul><h2 id="_2-網路磁碟機-network-drives" tabindex="-1">2. 網路磁碟機（Network Drives） <a class="header-anchor" href="#_2-網路磁碟機-network-drives" aria-label="Permalink to &quot;2. 網路磁碟機（Network Drives）&quot;">​</a></h2><ul><li><strong>網路儲存支援</strong>：展示所有已對應的 Windows 網路共用磁碟（SMB / NAS）。</li><li><strong>重新整理模式（Refresh Mode）</strong>：網路儲存缺乏本機 USN 記錄檔，因此支援自訂計劃輪詢策略： <ul><li><strong>手動</strong> —— 僅在按一下「重建索引」時重新掃描。</li><li><strong>每 15 分鐘</strong> —— 高頻協同辦公目錄推薦。</li><li><strong>每小時</strong> —— 均衡型定時掃描。</li><li><strong>每天</strong> —— 靜態封存共用推薦。</li></ul></li><li><strong>符號連結環路保護</strong>：掃描引擎內建了分支祖先路徑棧與符號連結循環偵測演算法，即使 NAS 共用中存在指向父級目錄的軟連結或重新分析點，也能自動攔截死循環，確保索引數量準確不膨脹。</li></ul><h2 id="_3-wsl-linux-子系統" tabindex="-1">3. WSL（Linux 子系統） <a class="header-anchor" href="#_3-wsl-linux-子系統" aria-label="Permalink to &quot;3. WSL（Linux 子系統）&quot;">​</a></h2><p>當且僅當系統偵測到至少安裝了一個 WSL 發行版時，本標籤頁會自動出現：</p><ul><li><strong>自動探測</strong>：自動識別 Ubuntu、Debian、Arch 等已安裝的 WSL 發行版。</li><li><strong>狀態與重新整理</strong>：提供與網路磁碟機完全一致的狀態監控與重新整理模式設定（手動 / 每 15 分鐘 / 每小時 / 每天）。</li><li><strong>零 I/O 搜尋</strong>：搜尋 WSL 檔案時直接查詢記憶體索引樹，完全不喚醒或阻塞 Linux 子系統。</li></ul><h2 id="_4-資料夾-folders" tabindex="-1">4. 資料夾（Folders） <a class="header-anchor" href="#_4-資料夾-folders" aria-label="Permalink to &quot;4. 資料夾（Folders）&quot;">​</a></h2><p>當你不希望索引整個磁碟機或整台 NAS 伺服器，而只想精準收錄特定工作目錄時，可以使用自訂資料夾索引：</p><ul><li><strong>多選新增</strong>：按一下<strong>新增資料夾</strong>按鈕開啟原生選取器，支援按住 <code>Ctrl</code> 或 <code>Shift</code> 一次性批次選取新增多個目錄。</li><li><strong>UNC 路徑支援</strong>：支援直接新增類似 <code>\\\\server\\share\\projects</code> 的區域網路 UNC 共用目錄。</li><li><strong>獨立計劃重新整理</strong>：每個資料夾均擁有獨立的啟用開關、項目計數與重新整理模式下拉框（手動 / 每 15 分鐘 / 每小時 / 每天）。</li></ul><h2 id="_5-排除規則-exclusions" tabindex="-1">5. 排除規則（Exclusions） <a class="header-anchor" href="#_5-排除規則-exclusions" aria-label="Permalink to &quot;5. 排除規則（Exclusions）&quot;">​</a></h2><p>排除規則全域作用於本機磁碟、網路儲存與自訂資料夾，分為三個子標籤頁：</p><h3 id="路徑排除-path-exclusions" tabindex="-1">路徑排除（Path Exclusions） <a class="header-anchor" href="#路徑排除-path-exclusions" aria-label="Permalink to &quot;路徑排除（Path Exclusions）&quot;">​</a></h3><ul><li><strong>比對機制</strong>：按完整實體路徑前綴進行精確屏蔽。</li><li><strong>環境變數支援</strong>：支援輸入 <code>%ProgramData%</code>、<code>%APPDATA%</code> 或 <code>D:\\Cache</code>。</li></ul><h3 id="glob-萬用字元排除-glob-rules" tabindex="-1">Glob 萬用字元排除（Glob Rules） <a class="header-anchor" href="#glob-萬用字元排除-glob-rules" aria-label="Permalink to &quot;Glob 萬用字元排除（Glob Rules）&quot;">​</a></h3><ul><li><strong>常見語法</strong>： <ul><li><code>*</code>：比對單層目錄內的任意字元（如 <code>*.tmp</code>、<code>*.log</code>）。</li><li><code>**</code>：跨層級遞迴比對任意子目錄（如 <code>**/node_modules/**</code>、<code>**/bin/**</code>、<code>**/obj/**</code>）。</li></ul></li></ul><h3 id="規則運算式排除-regex-rules" tabindex="-1">規則運算式排除（Regex Rules） <a class="header-anchor" href="#規則運算式排除-regex-rules" aria-label="Permalink to &quot;規則運算式排除（Regex Rules）&quot;">​</a></h3><ul><li><strong>進階過濾</strong>：針對完整路徑或檔案名稱進行正規比對。例如使用 <code>^\\.</code> 排除 Linux 式隱藏點檔案，使用 <code>~\\$</code> 排除 Office 產生的臨時鎖定檔案。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>排除規則支援<strong>單筆新增</strong>與<strong>批次匯入匯出</strong>：按一下<strong>從列表產生</strong>可將現有規則匯出為多行文字，編輯後按一下<strong>套用到列表</strong>即可一次性批次生效。修改排除規則後，相關磁碟機與資料夾會自動重新套用過濾。</p></div>',21)])])}const x=e(l,[["render",n]]);export{h as __pageData,x as default};
